/** The mark for an agent harness, by the name a session shows it under, or `undefined`. */
export function harnessMark(harness: string): ProviderMarkGlyph | undefined {
  const key = harness.trim().toLowerCase()
  return Object.hasOwn(HARNESS_MARKS, key) ? HARNESS_MARKS[key] : undefined
}

