const LANGUAGE_MARKS: Readonly<Record<string, ProviderMarkGlyph>> = {
  python: GLYPH_LANGUAGE_PYTHON,
  javascript: GLYPH_LANGUAGE_JAVASCRIPT,
  go: GLYPH_LANGUAGE_GO,
  java: GLYPH_LANGUAGE_JAVA,
  rust: GLYPH_LANGUAGE_RUST,
  ruby: GLYPH_LANGUAGE_RUBY,
}

/** The mark for a client's language, by the `client_language` a session carries, or `undefined`. */
export function languageMark(language: string): ProviderMarkGlyph | undefined {
  const key = language.trim().toLowerCase()
  return Object.hasOwn(LANGUAGE_MARKS, key) ? LANGUAGE_MARKS[key] : undefined
}

/**
 * The tables' own keys, for the drift gate beside `brandMarkKeys`.
 *
 * Exported for that comparison only. The app asks `hasProviderMark` and
 * `hasMakerMark`, which answer from the synchronous key lists rather than from
 * here, so that a page can decide its slots without fetching the geometry.
 */
export const MARK_TABLE_KEYS_FOR_TEST = {
  providers: Object.keys(PROVIDER_MARKS),
  makers: Object.keys(MAKER_MARKS),
  harnesses: Object.keys(HARNESS_MARKS),
  languages: Object.keys(LANGUAGE_MARKS),
}
